			if (light.length > 0) blocks.push(`/* variables (light) */\nbody {\n${light.join("\n")}\n}`);
			if (dark.length > 0) blocks.push(`/* variables (dark) */\nbody[data-ds-dark-theme] {\n${dark.join("\n")}\n}`);
